import os
from openai import OpenAI

def get_client(config=None):
    config = config or {}
    api_key = config.get('api_key') or os.environ['OPENAI_API_KEY']
    return OpenAI(api_key=api_key)

from.model_client import get_client

def check_safety(payload, config=None):
    client = get_client(config)
    response = client.moderations.create(input=payload['text'])
    return {'safe': not response.results[0].flagged}

from.model_client import get_client

def embed_output(payload, config=None):
    client = get_client(config)
    response = client.embeddings.create(input=payload['text'], model='text-embedding-ada-002')
    return {'embedding': response.data[0].embedding}
